// activeRobot no es el propio robot (state puede ser cualquier valor).
// Si estaba en WAIT_ROBOT (gantry encadenado), preserva waitingRobot.
if (true && sRobotEdge2 && activeRobot !== 2) {
    const _savedWR = c.get('waitingRobot');
    if (typeof _savedWR === 'number' && _savedWR >= 0) c.set('waitingRobot6ax', _savedWR);
    state = 'ROBOT';
    activeRobot = 2;
    rstep = ROBOT_START_STEPS[2]; 
    c.set('r2Armed', false);
    for (let i = 0; i < ROB_COUNT; i++) {
        execHigh[i] = false; execLowSince[i] = 0; execHighSince[i] = 0;
    }
    c.set('vacDwellUntil', 0);
    c.set('stepPulseUntil', 0);
    indexingBeltsPulse(false);
    feedControl();
    w(ROB[2].vacuum.name, ROB[2].vacuum.path, false);
}

switch (state) {
    case 'RUN':
        if (true && sRobotEdge0 && robotTurnAllows(0)) {
            state = 'ROBOT';
            activeRobot = 0;
            rstep = ROBOT_START_STEPS[0];
            c.set('robotPending0', false);
            for (let i = 0; i < ROB_COUNT; i++) {
                execHigh[i] = false; execLowSince[i] = 0; execHighSince[i] = 0;
            }
            c.set('vacDwellUntil', 0);
            c.set('stepPulseUntil', 0);
            indexingBeltsPulse(false);
            c.set('mqStarted', false);
            c.set('mqFinished', false);
            c.set('mqStep', 0);
            c.set('mqTarget', null);
            c.set('mqDwellUntil', 0);
            feedControl();
            w(ROB[0].vacuum.name, ROB[0].vacuum.path, false);
        } else if (false && sRobotEdge1 && robotTurnAllows(1) && indexingIdle()) {
            state = 'ROBOT';
            activeRobot = 1;
            rstep = ROBOT_START_STEPS[1];
            c.set('robotPending1', false);
            for (let i = 0; i < ROB_COUNT; i++) {
                execHigh[i] = false; execLowSince[i] = 0; execHighSince[i] = 0;
            }
            c.set('vacDwellUntil', 0);
            c.set('stepPulseUntil', 0);
            indexingBeltsPulse(false);
            c.set('mqStarted', false);
            c.set('mqFinished', false);
            c.set('mqStep', 0);
            c.set('mqTarget', null);
            c.set('mqDwellUntil', 0);
            feedControl();
            w(ROB[1].vacuum.name, ROB[1].vacuum.path, false);
        } else {
            feedControl();
            indexingBeltsPulse(false);
        }
        break;

    case 'ROBOT':
        feedControl();
        if (now < (c.get('stepPulseUntil') || 0)) {
            indexingBeltsPulse(true);
        } else {
            indexingBeltsPulse(false);
        }
        switch (rstep) {
            case 0: // R0 mover a cmd 1
                if (robotMove(0, 1)) rstep = 1;
                break;
            case 1: // R0 vacuum true
                    w(ROB[0].vacuum.name, ROB[0].vacuum.path, true);
                    c.set('vacDwellUntil', now + VAC_DWELL_MS);
                    rstep = 2;
                break;
            case 2: // esperar vacuum
                if (now >= c.get('vacDwellUntil')) rstep = 3;
                break;
            case 3: // R0 mover a cmd 0
                if (robotMove(0, 0)) rstep = 4;
                break;
            case 4: // R0 mover a cmd 2
                if (robotMove(0, 2)) rstep = 5;
                break;
            case 5: // R0 mover a cmd 3
                if (robotMove(0, 3)) rstep = 6;
                break;
            case 6: // R0 vacuum false
                    w(ROB[0].vacuum.name, ROB[0].vacuum.path, false);
                    c.set('vacDwellUntil', now + VAC_DWELL_MS);
                    rstep = 7;
                break;
            case 7: // esperar vacuum + pulso indexing
                if (now >= c.get('vacDwellUntil')) {
                    c.set('stepPulseUntil', now + STEP_PULSE_MS);
                    countBatchUnit();
                    startMaquina();
                    hornoFire();
                    waitForRobot(1);
                }
                break;
            case 8: // R1 mover a cmd 1
                if (robotMove(1, 1)) rstep = 9;
                break;
            case 9: // R1 vacuum true
                    w(ROB[1].vacuum.name, ROB[1].vacuum.path, true);
                    c.set('vacDwellUntil', now + VAC_DWELL_MS);
                    rstep = 10;
                break;
            case 10: // esperar vacuum
                if (now >= c.get('vacDwellUntil')) rstep = 11;
                break;
            case 11: // R1 mover a cmd 0
                if (robotMove(1, 0)) rstep = 12;
                break;
            case 12: // R1 mover a cmd 2
                if (robotMove(1, 2)) rstep = 13;
                break;
            case 13: // R1 mover a cmd 3
                if (robotMove(1, 3)) rstep = 14;
                break;
            case 14: // R1 vacuum false
                    w(ROB[1].vacuum.name, ROB[1].vacuum.path, false);
                    c.set('vacDwellUntil', now + VAC_DWELL_MS);
                    rstep = 15;
                break;
            case 15: // esperar vacuum
                if (now >= c.get('vacDwellUntil')) finishRobotSequence();
                break;
            case 16: // R2 mover a cmd 1
                if (robotMove(2, 1)) rstep = 17;
                break;
            case 17: // R2 vacuum true
                    w(ROB[2].vacuum.name, ROB[2].vacuum.path, true);
                    c.set('vacDwellUntil', now + VAC_DWELL_MS);
                    rstep = 18;
                break;
            case 18: // esperar vacuum
                if (now >= c.get('vacDwellUntil')) rstep = 19;
                break;
            case 19: // R2 mover a cmd 2
                if (robotMove(2, 2)) rstep = 20;
                break;
            case 20: // R2 mover a cmd 3
                if (robotMove(2, 3)) rstep = 21;
                break;
            case 21: // R2 vacuum false
                    w(ROB[2].vacuum.name, ROB[2].vacuum.path, false);
                    c.set('vacDwellUntil', now + VAC_DWELL_MS);
                    rstep = 22;
                break;
            case 22: // esperar vacuum
                if (now >= c.get('vacDwellUntil')) rstep = 23;
                break;
            case 23: // R2 mover a cmd 1
                if (robotMove(2, 1)) rstep = 24;
                break;
            case 24: // R2 vacuum true
                    w(ROB[2].vacuum.name, ROB[2].vacuum.path, true);
                    c.set('vacDwellUntil', now + VAC_DWELL_MS);
                    rstep = 25;
                break;
            case 25: // esperar vacuum
                if (now >= c.get('vacDwellUntil')) rstep = 26;
                break;
            case 26: // R2 mover a cmd grid[4,5,6,7,8,9,10,11]
                if (robotMoveGrid(2)) rstep = 27;
                break;
            case 27: // R2 vacuum false
                    w(ROB[2].vacuum.name, ROB[2].vacuum.path, false);
                    c.set('vacDwellUntil', now + VAC_DWELL_MS);
                    rstep = 28;
                break;
            case 28: // esperar vacuum
                if (now >= c.get('vacDwellUntil')) finishRobotSequence();
                break;
        }
        maquinaRun();
        break;

    case 'WAIT_ROBOT':
        feedControl();
        if (now < (c.get('stepPulseUntil') || 0)) {
            indexingBeltsPulse(true);
        } else {
            indexingBeltsPulse(false);
        }
        const waitingRobot = c.get('waitingRobot');
        if (waitingRobot >= 0 && waitingRobot < ROB_COUNT && ROBOT_PENDING[waitingRobot] && indexingIdle()) {
            activeRobot = waitingRobot;
            c.set('robotPending' + waitingRobot, false);
            c.set('waitingRobot', -1);
            for (let i = 0; i < ROB_COUNT; i++) {
                execHigh[i] = false; execLowSince[i] = 0; execHighSince[i] = 0;
            }
            c.set('vacDwellUntil', 0);
            state = 'ROBOT';
        }
        maquinaRun();
        break;

    case 'BATCH_GAP':
        feedControl();
        if (now < (c.get('stepPulseUntil') || 0)) {
            indexingBeltsPulse(true);
        } else {
            indexingBeltsPulse(false);
            const nextAt = c.get('batchGapNextAt') || 0;
            if (!nextAt) {
                c.set('batchGapNextAt', now + STEP_PULSE_MS);
            } else if (now >= nextAt) {
                const remaining = (c.get('batchGapRemaining') || 0) - 1;
                c.set('batchGapRemaining', remaining);
                if (remaining <= 0) {
                    c.set('batchGapNextAt', 0);
                    state = 'RUN';
                } else {
                    c.set('batchGapNextAt', 0);
                    c.set('stepPulseUntil', now + STEP_PULSE_MS);
                }
            }
        }
        maquinaRun();
        break;
}
hornoRun();

c.set('state', state);
c.set('rstep', rstep);
c.set('activeRobot', activeRobot);
c.set('nextRobot', nextRobot);
c.set('execHigh', execHigh);
c.set('execLowSince', execLowSince);
c.set('execHighSince', execHighSince);
c.set('batchUnitCount', c.get('batchUnitCount') || 0);
c.set('batchGapPending', c.get('batchGapPending') || false);
c.set('batchGapRemaining', c.get('batchGapRemaining') || 0);
c.set('batchGapNextAt', c.get('batchGapNextAt') || 0);

if (writes.length === 0) return null;
msg.payload = writes;
return msg;
